# Décisions manuelles de la deuxième passe : (paire triée) -> (catégorie, entité à qui on retire, note)
PASSE2 = {}
def p2(a, b, cat, cut, note):
    PASSE2[tuple(sorted((a, b)))] = (cat, cut, note)
